def _err(kind: str, msg: str, tool: str, **extra) -> dict:
    """统一错误构造：保留 'error' 键兼容老调用方，新增 'error_kind' 和 'tool'。
    tool 用于错误溯源（传入工具函数名）。
    extra 用于附加 returncode/stdout/stderr 之类的辅助字段。"""
    assert kind in ERROR_KINDS, f"unknown error_kind: {kind}"
    out = {"error": msg, "error_kind": kind, "tool": tool}
    if extra:
        out.update(extra)
    return out
